    <div class="plantations-workspace"><section class="proposal-admin-list"><h3>Liste des propositions</h3><?php if ($displayFeatures === []): ?><p>Aucune plantation.</p><?php endif; ?><?php foreach ($displayFeatures as $feature): $properties = $feature['properties'] ?? []; $coordinates = $feature['geometry']['coordinates'] ?? [null, null]; $id = (string) ($properties['id'] ?? ''); ?>
      <?php if ($isAdministrator): ?><form class="proposal-admin-card" data-proposal-id="<?= htmlspecialchars($id) ?>" method="post" action="/admin/propositions/modifier"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="id" value="<?= htmlspecialchars($id) ?>">
        <label>Essence<select name="species"><?php foreach ($planting['allowed_species'] as $species): ?><option value="<?= htmlspecialchars($species) ?>" <?= ($properties['species'] ?? '') === $species ? 'selected' : '' ?>><?= htmlspecialchars($species) ?></option><?php endforeach; ?></select></label>
        <fieldset><legend>Objectifs <small>3 maximum</small></legend><div class="objective-grid admin-objectives"><?php foreach ($planting['objectives'] as $key => $objective): ?><label class="objective"><input type="checkbox" name="objectives[]" value="<?= htmlspecialchars($key) ?>" <?= in_array($key, $properties['objectives'] ?? [], true) ? 'checked' : '' ?>><span class="objective-tile"><span class="objective-icon"><?= htmlspecialchars($objective['icon']) ?></span><span><?= htmlspecialchars($objective['label']) ?></span></span></label><?php endforeach; ?></div></fieldset>
        <label>Statut<select name="status"><?php $shownStatuses = []; foreach ($statuses as $value => $label): if (isset($shownStatuses[$label])) { continue; } $shownStatuses[$label] = true; ?><option value="<?= htmlspecialchars($value) ?>" <?= ($properties['status'] ?? 'a_valider') === $value ? 'selected' : '' ?>><?= htmlspecialchars($label) ?></option><?php endforeach; ?></select></label><div class="coordinate-fields"><label>Longitude<input type="number" name="longitude" step="any" value="<?= htmlspecialchars((string) $coordinates[0]) ?>" required></label><label>Latitude<input type="number" name="latitude" step="any" value="<?= htmlspecialchars((string) $coordinates[1]) ?>" required></label></div><button>Enregistrer</button>
      </form><?php else: ?><article class="proposal-admin-card" data-proposal-id="<?= htmlspecialchars($id) ?>"><h3><?= htmlspecialchars((string) ($properties['species'] ?? 'Plantation')) ?></h3><p><?= htmlspecialchars(implode(', ', $properties['objectives'] ?? [])) ?></p><p><?= htmlspecialchars($statuses[$properties['status'] ?? 'a_valider'] ?? 'Proposée') ?></p></article><?php endif; ?>
    <?php endforeach; ?></section><aside class="plantations-map-panel"><h3>Carte</h3><p><?= $isAdministrator ? 'Faites glisser un repère pour modifier ses coordonnées.' : 'Vos propositions géolocalisées.' ?></p><div id="plantations-map" class="account-map"></div><section id="proposal-details" class="proposal-details" hidden><h4>Détail de la proposition</h4><p id="proposal-comment"></p><div id="proposal-photos" class="proposal-photo-gallery"></div></section></aside></div>
  <?php elseif ($tab === 'utilisateurs'): ?>
    <h2>Gestion des utilisateurs</h2><?php if ($notice): ?><p class="form-message success"><?= htmlspecialchars($notice) ?></p><?php endif; ?>
    <section class="create-user"><h3 id="user-form-title">Créer un utilisateur</h3><p id="user-form-help">Le nouvel utilisateur recevra un e-mail pour définir son mot de passe lors de sa première connexion.</p><form id="user-form" method="post" action="/admin/utilisateurs/creer"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input id="edited-user-id" type="hidden" name="user_id"><div class="coordinate-fields"><label>Prénom<input id="edited-first-name" name="first_name" required autocomplete="given-name"></label><label>Nom<input id="edited-last-name" name="last_name" required autocomplete="family-name"></label></div><label>E-mail<input id="edited-email" name="email" type="email" required autocomplete="email"></label><?php if ($user['role'] === 'administrateur'): ?><label class="role-toggle"><input id="role-administrator" name="role" type="checkbox" value="administrateur"> Administrateur</label><?php else: ?><fieldset class="role-options"><legend>Rôle</legend><label><input type="radio" name="role" value="contributeur" checked> Contributeur</label><label><input type="radio" name="role" value="administrateur"> Administrateur</label><label><input type="radio" name="role" value="super_administrateur"> Super-admin</label></fieldset><?php endif; ?><div class="inline-actions"><button id="user-form-submit">Créer et envoyer l’invitation</button><button id="user-form-reset" type="button">Nouveau</button></div></form></section>
    <table class="users-table"><thead><tr><th>Nom</th><th>E-mail</th><th>Rôle</th><th>Action</th></tr></thead><tbody><?php foreach ($users as $listedUser): ?><tr class="user-row" tabindex="0" data-user-id="<?= htmlspecialchars($listedUser['id']) ?>" data-first-name="<?= htmlspecialchars($listedUser['first_name']) ?>" data-last-name="<?= htmlspecialchars($listedUser['last_name']) ?>" data-email="<?= htmlspecialchars($listedUser['email']) ?>" data-role="<?= htmlspecialchars($listedUser['role']) ?>"><td><?= htmlspecialchars($listedUser['first_name'] . ' ' . $listedUser['last_name']) ?></td><td><?= htmlspecialchars($listedUser['email']) ?></td><td><?= htmlspecialchars(str_replace('_', ' ', $listedUser['role'])) ?></td><td><?php if ($listedUser['role'] === 'super_administrateur'): ?>Protégé<?php elseif ($user['role'] === 'administrateur' && $listedUser['role'] === 'contributeur'): ?><form method="post" action="/admin/utilisateurs/role"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="user_id" value="<?= htmlspecialchars($listedUser['id']) ?>"><input type="hidden" name="role" value="administrateur"><button>Passer administrateur</button></form><?php elseif ($user['role'] === 'super_administrateur' && $listedUser['role'] === 'administrateur'): ?><div class="inline-actions"><form method="post" action="/admin/utilisateurs/role"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="user_id" value="<?= htmlspecialchars($listedUser['id']) ?>"><input type="hidden" name="role" value="contributeur"><button>Rétrograder</button></form><form method="post" action="/admin/utilisateurs/role"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="user_id" value="<?= htmlspecialchars($listedUser['id']) ?>"><input type="hidden" name="role" value="super_administrateur"><button>Passer super-admin</button></form></div><?php endif; ?></td></tr><?php endforeach; ?></tbody></table>
  <?php endif; ?>
</main><?php require __DIR__ . '/../partials/footer.php'; ?>
<?php if ($tab === 'plantations'): ?><dialog id="photo-dialog" class="photo-dialog"><button type="button" class="dialog-close" aria-label="Fermer">×</button><img id="photo-dialog-image" alt="Photo de la proposition"></dialog><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const proposalFeatures=<?= json_encode($displayFeatures, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;const canEdit=<?= $isAdministrator ? 'true' : 'false' ?>;const map=L.map('plantations-map').setView([47.531,-0.102],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);const cards=[...document.querySelectorAll('[data-proposal-id]')],details=document.querySelector('#proposal-details'),comment=document.querySelector('#proposal-comment'),gallery=document.querySelector('#proposal-photos'),photoDialog=document.querySelector('#photo-dialog'),dialogImage=document.querySelector('#photo-dialog-image');const imageUrl=path=>`/${String(path).replace(/^\/+/, '')}`,dateFormat=new Intl.DateTimeFormat('fr-FR',{dateStyle:'long',timeStyle:'short'});const showDetails=feature=>{const properties=feature.properties||{};details.hidden=false;comment.textContent=properties.comment||'Aucun commentaire.';gallery.replaceChildren();const photos=Array.isArray(properties.photos)?properties.photos:[];if(!photos.length){const empty=document.createElement('p');empty.textContent='Aucune photo.';gallery.append(empty);return;}photos.forEach((path,index)=>{const button=document.createElement('button'),image=document.createElement('img');button.type='button';button.className='proposal-photo-thumbnail';image.src=imageUrl(path);image.alt=`Photo ${index+1} de la proposition`;button.append(image);button.addEventListener('click',()=>{dialogImage.src=imageUrl(path);photoDialog.showModal();});gallery.append(button);});};const selectProposal=(id,feature)=>{cards.forEach(card=>{card.hidden=card.dataset.proposalId!==id;});const card=document.querySelector(`[data-proposal-id="${id}"]`);if(card){card.scrollIntoView({behavior:'smooth',block:'center'});}showDetails(feature);};document.querySelector('.dialog-close').addEventListener('click',()=>photoDialog.close());photoDialog.addEventListener('click',event=>{if(event.target===photoDialog)photoDialog.close();});if(proposalFeatures.length>1)cards.forEach(card=>{card.hidden=true;});const markers=[];proposalFeatures.forEach(feature=>{const [lng,lat]=feature.geometry.coordinates,properties=feature.properties||{},createdAt=properties.created_at?dateFormat.format(new Date(properties.created_at)):'';const marker=L.marker([lat,lng],{draggable:canEdit}).addTo(map);marker.bindPopup(`<strong>${properties.species||'Plantation'}</strong>${createdAt?`<br><small>${createdAt}</small>`:''}`);marker.on('click',()=>selectProposal(properties.id,feature));markers.push(marker);if(canEdit){marker.on('dragend',()=>{const position=marker.getLatLng();const form=document.querySelector(`[data-proposal-id="${properties.id}"]`);if(form){form.querySelector('[name="longitude"]').value=position.lng.toFixed(6);form.querySelector('[name="latitude"]').value=position.lat.toFixed(6);selectProposal(properties.id,feature);}});}});if(markers.length){map.fitBounds(L.featureGroup(markers).getBounds(),{padding:[24,24]});}document.querySelectorAll('.admin-objectives').forEach(grid=>grid.addEventListener('change',event=>{if(grid.querySelectorAll('input:checked').length>3){event.target.checked=false;window.alert('Trois objectifs maximum.');}}));</script><?php endif; ?>
<?php if ($tab === 'utilisateurs'): ?><script>const userForm=document.querySelector('#user-form'),userTitle=document.querySelector('#user-form-title'),userHelp=document.querySelector('#user-form-help'),userSubmit=document.querySelector('#user-form-submit'),userId=document.querySelector('#edited-user-id'),userFirstName=document.querySelector('#edited-first-name'),userLastName=document.querySelector('#edited-last-name'),userEmail=document.querySelector('#edited-email');const resetUserForm=()=>{userForm.reset();userForm.action='/admin/utilisateurs/creer';userId.value='';userTitle.textContent='Créer un utilisateur';userHelp.hidden=false;userSubmit.textContent='Créer et envoyer l’invitation';document.querySelectorAll('.user-row').forEach(row=>row.classList.remove('selected'));};const editUser=row=>{userId.value=row.dataset.userId;userFirstName.value=row.dataset.firstName;userLastName.value=row.dataset.lastName;userEmail.value=row.dataset.email;userForm.action='/admin/utilisateurs/modifier';userTitle.textContent='Modifier un utilisateur';userHelp.hidden=true;userSubmit.textContent='Mettre à jour le profil';document.querySelectorAll('.user-row').forEach(item=>item.classList.toggle('selected',item===row));const role=row.dataset.role,checkbox=document.querySelector('#role-administrator');if(checkbox){checkbox.checked=role==='administrateur';}else{const option=document.querySelector(`[name="role"][value="${role}"]`);if(option)option.checked=true;}};document.querySelector('#user-form-reset').addEventListener('click',resetUserForm);document.querySelectorAll('.user-row').forEach(row=>{row.addEventListener('click',event=>{if(event.target.closest('form,button,a'))return;editUser(row);});row.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();editUser(row);}});});</script><?php endif; ?>
</body></html>
